// Data-driven robot definition: model, rig, stats, AI tuning and hacking rules.
using System.Collections.Generic;
using UnityEngine;

namespace Metalization
{
    /// <summary>
    /// Fully describes one kind of robot (Player, Shooter, Soldier, Brute, Sentry, Stalker...). MetalBot.ApplyArchetype
    /// reads it to build the model, capsule, movement, weapons and hit zones, and the AI controllers read the AI
    /// section for their tuning. Generated by the asset pipeline into Assets/Metalization/Data (DA_Bot_*).
    /// </summary>
    [CreateAssetMenu(menuName = "Metalization/Bot Archetype", fileName = "DA_Bot_")]
    public class MetalBotArchetype : ScriptableObject
    {
        [Header("Identity")]
        [Tooltip("Matches the key used in MetalWeaponLevel.heldModels (\"player\", \"shooter\").")]
        public string archetypeId = "";
        public string displayName = "";
        public MetalTeam team = MetalTeam.Villains;

        [Header("Visual")]
        [Tooltip("Body model (FBX). Its skeleton must contain the bones named in rig.")]
        public GameObject model;
        [Tooltip("Extra body parts skinned to the same skeleton (backpacks, visors, built-in tools).")]
        public List<GameObject> parts = new List<GameObject>();
        [Tooltip("Shown instead of a held weapon (e.g. the player's right hand).")]
        public GameObject unarmedPart;
        public float meshScale = 1f;
        [Tooltip("Extra offset of the model from the bottom of the capsule, metres.")]
        public Vector3 meshOffset = Vector3.zero;
        [Tooltip("Team paint. Robots without an entry keep their imported colours.")]
        public List<MetalTeamColors> teamColors = new List<MetalTeamColors>();
        public MetalBotRig rig = new MetalBotRig();

        [Header("Body")]
        public float capsuleRadius = 0.34f;
        public float capsuleHalfHeight = 0.68f;
        [Tooltip("Pitch of this robot type's voice: 1 as recorded, 0.5 an octave lower.")]
        [Range(0.3f, 2f)] public float voicePitch = 1f;
        public float maxHealth = 100f;
        [Tooltip("Top running speed on the ground, m/s.")]
        public float walkSpeed = 5f;
        [Tooltip("Upward launch speed of a jump, m/s.")]
        public float jumpVelocity = 6f;
        [Tooltip("2 gives a mid-air double jump (played as a forward flip).")]
        public int maxJumps = 1;
        [Tooltip("Top speed while sprinting. 0 = can't sprint.")]
        public float sprintSpeed;
        [Tooltip("Top speed while sneaking (crouched). 0 = can't crouch.")]
        public float crouchSpeed;
        [Tooltip("Capsule half height while crouched, as a fraction of capsuleHalfHeight.")]
        public float crouchHeightFraction = 0.65f;
        [Tooltip("Wears a jetpack whose thrusters fire on the mid-air jump.")]
        public bool hasJetpack;
        [Tooltip("Weak points and breakable parts.")]
        public List<MetalHitZone> hitZones = new List<MetalHitZone>();

        [Header("Combat")]
        [Tooltip("Weapon swaps are acted out (twist off, rack on the back, snap on). Player-driven only.")]
        public bool animatedWeaponSwap;
        public float weaponSwapDuration = 0.8f;
        [Tooltip("Weapons this robot spawns with. The first one is equipped.")]
        public List<MetalWeaponData> startingWeapons = new List<MetalWeaponData>();
        [Tooltip("Used when the weapon arm is destroyed.")]
        public MetalWeaponData meleeWeapon;
        public MetalWeaponData grenadeWeapon;
        public int startingGrenades;
        [Tooltip("Built-in guns (Brute miniguns) fire from these bones instead of the weapon bone.")]
        public List<string> muzzleBones = new List<string>();
        [Tooltip("Built-in second weapon (Brute shoulder rockets). Level 0 fireInterval is its cooldown.")]
        public MetalWeaponData secondaryWeapon;
        public string secondaryMuzzleBone = "";

        [Header("AI")]
        [Tooltip("Vision distance, metres.")]
        public float sightRange = 35f;
        public float sightHalfAngle = 70f;
        [Tooltip("Distance the robot tries to keep from its target, metres.")]
        public float preferredRange = 9f;
        public float aimErrorDegrees = 4f;
        public float burstDuration = 1.2f;
        public float burstPause = 1f;
        [Tooltip("Health fraction below which the robot falls back to cover. 0 = never.")]
        public float retreatHealthFraction;
        [Tooltip("Nearby allies within this radius (m) join the fight when this robot spots an enemy.")]
        public float squadAlertRadius = 20f;

        [Header("Hacking")]
        public bool hackable = true;
        [Tooltip("Seconds the player can control this robot with the Hack Tether.")]
        public float possessionDuration = 30f;
        [Tooltip("Robots of the player's own team can be linked (parked Stalkers): no time limit.")]
        public bool allyHackable;

        [Header("Flight")]
        public MetalFlightTuning flight = new MetalFlightTuning();

        [Header("Camera")]
        [Tooltip("Third-person camera boom length when a player drives this robot, metres.")]
        public float cameraDistance = 3f;
        [Tooltip("Over-the-shoulder offset of the camera from the end of the boom (right, up, 0), metres.")]
        public Vector3 cameraOffset = new Vector3(0.55f, 0.55f, 0f);

        public MetalTeamColors GetTeamColors(MetalTeam forTeam)
        {
            foreach (MetalTeamColors c in teamColors)
            {
                if (c.team == forTeam) return c;
            }
            return null;
        }
    }
}
